#'
#' @export
StandardNormalDistribution <- function(
    data,
    mean,
    sd,
    X) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("StandardNormalDistribution requires jmvcore to be installed (restart may be required)")

    if ( ! missing(mean)) mean <- jmvcore::resolveQuo(jmvcore::enquo(mean))
    if ( ! missing(sd)) sd <- jmvcore::resolveQuo(jmvcore::enquo(sd))
    if ( ! missing(X)) X <- jmvcore::resolveQuo(jmvcore::enquo(X))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(mean), mean, NULL),
            `if`( ! missing(sd), sd, NULL),
            `if`( ! missing(X), X, NULL))


    options <- StandardNormalDistributionOptions$new(
        mean = mean,
        sd = sd,
        X = X)

    analysis <- StandardNormalDistributionClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

